import type { File } from "@babel/core";
import type { NodePath, Visitor } from "@babel/traverse";
import traverse from "@babel/traverse";
import {
  assignmentExpression,
  cloneNode,
  expressionStatement,
  file,
  identifier,
  BUILDER_KEYS,
  NODE_FIELDS,
  validate,
} from "@babel/types";
import type * as t from "@babel/types";
import helpers from "./helpers.ts";

function makePath(path: NodePath) {
  const parts = [];

  for (; path.parentPath; path = path.parentPath) {
    parts.push(path.key);
    if (path.inList) parts.push(path.listKey);
  }

  return parts.reverse().join(".");
}

let FileClass: typeof File | undefined = undefined;

interface HelperMetadata {
  globals: string[];
  localBindingNames: string[];
  dependencies: Map<t.Identifier, string>;
  exportBindingAssignments: string[];
  exportPath: string;
  exportName: string;
  importBindingsReferences: string[];
  importPaths: string[];
}

/**
 * Given a file AST for a given helper, get a bunch of metadata about it so that Babel can quickly render
 * the helper is whatever context it is needed in.
 */
function getHelperMetadata(file: File): HelperMetadata {
  const globals = new Set<string>();
  const localBindingNames = new Set<string>();
  // Maps imported identifier -> helper name
  const dependencies = new Map<t.Identifier, string>();

  let exportName: string | undefined;
  let exportPath: string | undefined;
  const exportBindingAssignments: string[] = [];
  const importPaths: string[] = [];
  const importBindingsReferences: string[] = [];

  const dependencyVisitor: Visitor = {
    ImportDeclaration(child) {
      const name = child.node.source.value;
      if (!helpers[name]) {
        throw child.buildCodeFrameError(`Unknown helper ${name}`);
      }
      if (
        child.get("specifiers").length !== 1 ||
        // @ts-expect-error isImportDefaultSpecifier does not work with NodePath union
        !child.get("specifiers.0").isImportDefaultSpecifier()
      ) {
        throw child.buildCodeFrameError(
          "Helpers can only import a default value",
        );
      }
      const bindingIdentifier = child.node.specifiers[0].local;
      dependencies.set(bindingIdentifier, name);
      importPaths.push(makePath(child));
    },
    ExportDefaultDeclaration(child) {
      const decl = child.get("declaration");

      if (!decl.isFunctionDeclaration() || !decl.node.id) {
        throw decl.buildCodeFrameError(
          "Helpers can only export named function declarations",
        );
      }

      exportName = decl.node.id.name;
      exportPath = makePath(child);
    },
    ExportAllDeclaration(child) {
      throw child.buildCodeFrameError("Helpers can only export default");
    },
    ExportNamedDeclaration(child) {
      throw child.buildCodeFrameError("Helpers can only export default");
    },
    Statement(child) {
      if (child.isImportDeclaration() || child.isExportDeclaration()) return;

      child.skip();
    },
  };

  const referenceVisitor: Visitor = {
    Program(path) {
      const bindings = path.scope.getAllBindings();

      Object.keys(bindings).forEach(name => {
        if (name === exportName) return;
        if (dependencies.has(bindings[name].identifier)) return;

        localBindingNames.add(name);
      });
    },
    ReferencedIdentifier(child) {
      const name = child.node.name;
      const binding = child.scope.getBinding(name);
      if (!binding) {
        globals.add(name);
      } else if (dependencies.has(binding.identifier)) {
        importBindingsReferences.push(makePath(child));
      }
    },
    AssignmentExpression(child) {
      const left = child.get("left");

      if (!(exportName in left.getBindingIdentifiers())) return;

      if (!left.isIdentifier()) {
        throw left.buildCodeFrameError(
          "Only simple assignments to exports are allowed in helpers",
        );
      }

      const binding = child.scope.getBinding(exportName);

      if (binding?.scope.path.isProgram()) {
        exportBindingAssignments.push(makePath(child));
      }
    },
  };

  traverse(file.ast, dependencyVisitor, file.scope);
  traverse(file.ast, referenceVisitor, file.scope);

  if (!exportPath) throw new Error("Helpers must have a default export.");

  // Process these in reverse so that mutating the references does not invalidate any later paths in
  // the list.
  exportBindingAssignments.reverse();

  return {
    globals: Array.from(globals),
    localBindingNames: Array.from(localBindingNames),
    dependencies,
    exportBindingAssignments,
    exportPath,
    exportName,
    importBindingsReferences,
    importPaths,
  };
}

type GetDependency = (name: string) => t.Expression;

/**
 * Given a helper AST and information about how it will be used, update the AST to match the usage.
 */
function permuteHelperAST(
  file: File,
  metadata: HelperMetadata,
  id?: t.Identifier | t.MemberExpression,
  localBindings?: string[],
  getDependency?: GetDependency,
) {
  if (localBindings && !id) {
    throw new Error("Unexpected local bindings for module-based helpers.");
  }

  if (!id) return;

  const {
    localBindingNames,
    exportBindingAssignments,
    exportPath,
    exportName,
    importBindingsReferences,
  } = metadata;

  const { path } = file;
  const dependenciesRefs: Record<string, t.Expression> = {};
  const collectedImportPaths: NodePath<t.ImportDeclaration>[] = [];
  const programBody = path.get("body");

  for (const child of programBody) {
    if (child.isImportDeclaration()) {
      const helperName = child.node.source.value;
      const helperEntry = helpers[helperName];
      if (!helperEntry) {
        throw child.buildCodeFrameError(`Unknown helper ${helperName}`);
      }
      const specifiers = child.get("specifiers");
      if (
        specifiers.length !== 1 ||
        // @ts-expect-error isImportDefaultSpecifier does not work with NodePath union
        !child.get("specifiers.0").isImportDefaultSpecifier()
      ) {
        throw child.buildCodeFrameError(
          "Helpers can only import a default value",
        );
      }
      const bindingIdentifier = child.node.specifiers[0].local;
      let resolved: t.Expression = bindingIdentifier;
      if (typeof getDependency === "function") {
        const provided = getDependency(helperName);
        if (provided) {
          resolved = provided;
        }
      }
      dependenciesRefs[bindingIdentifier.name] = resolved;
      collectedImportPaths.push(child);
      continue;
    }

    if (child.isExportDefaultDeclaration()) {
      const declarationPath = child.get("declaration");
      if (
        !declarationPath.isFunctionDeclaration() ||
        !declarationPath.node.id
      ) {
        throw declarationPath.buildCodeFrameError(
          "Helpers can only export named function declarations",
        );
      }
      const exportParts = [];
      let cursor: NodePath | null = child;
      for (; cursor && cursor.parentPath; cursor = cursor.parentPath) {
        exportParts.push(cursor.key);
        if (cursor.inList) {
          exportParts.push(cursor.listKey);
        }
      }
      const computedExportPath = exportParts.reverse().join(".");
      if (!exportPath && !computedExportPath) {
        throw new Error("Helpers must have a default export.");
      }
      continue;
    }

    if (child.isExportAllDeclaration()) {
      throw child.buildCodeFrameError("Helpers can only export default");
    }

    if (child.isExportNamedDeclaration()) {
      throw child.buildCodeFrameError("Helpers can only export default");
    }
  }

  const toRename: Record<string, string> = {};
  const bindings = new Set(localBindings || []);
  for (
    let bindingIndex = 0;
    bindingIndex < localBindingNames.length;
    bindingIndex++
  ) {
    const name = localBindingNames[bindingIndex];
    let newName = name;
    while (bindings.has(newName)) {
      newName = "_" + newName;
    }
    if (newName !== name) {
      toRename[name] = newName;
    }
  }

  if (id.type === "Identifier" && exportName !== id.name) {
    toRename[exportName] = id.name;
  }

  const exp: NodePath<t.ExportDefaultDeclaration> = path.get(exportPath);
  const imps: NodePath<t.ImportDeclaration>[] = [];
  for (const importNodePath of collectedImportPaths) {
    imps.push(importNodePath);
  }

  const impsBindingRefs: NodePath<t.Identifier>[] = [];
  for (const refPath of importBindingsReferences) {
    const bindingPath = path.get(refPath);
    if (!Array.isArray(bindingPath)) {
      impsBindingRefs.push(bindingPath as NodePath<t.Identifier>);
    }
  }

  const exportPathNode = exp;
  const decl = exportPathNode.get(
    "declaration",
  ) as NodePath<t.FunctionDeclaration>;

  if (id.type === "Identifier") {
    exportPathNode.replaceWith(decl);
  } else if (id.type === "MemberExpression") {
    for (const assignPath of exportBindingAssignments) {
      const assign = path.get(assignPath);
      if (Array.isArray(assign)) {
        continue;
      }
      const rightNode = (assign as NodePath<t.Expression>).node;
      const assignmentNode = assignmentExpression("=", id, rightNode);
      const assignKeys = BUILDER_KEYS[assignmentNode.type] as
        | (keyof t.AssignmentExpression & string)[]
        | undefined;
      if (assignKeys) {
        for (const key of assignKeys) {
          validate(assignmentNode, key, assignmentNode[key]);
        }
      }
      assign.replaceWith(assignmentNode);
    }

    exportPathNode.replaceWith(decl);

    const exportIdentifier = identifier(exportName);
    const identifierKeys = BUILDER_KEYS[exportIdentifier.type] as
      | (keyof t.Identifier & string)[]
      | undefined;
    if (identifierKeys) {
      for (const key of identifierKeys) {
        validate(exportIdentifier, key, exportIdentifier[key]);
      }
    }

    const exportAssignment = assignmentExpression("=", id, exportIdentifier);
    const exportAssignKeys = BUILDER_KEYS[exportAssignment.type] as
      | (keyof t.AssignmentExpression & string)[]
      | undefined;
    if (exportAssignKeys) {
      for (const key of exportAssignKeys) {
        validate(exportAssignment, key, exportAssignment[key]);
      }
    }

    const exportStatement = expressionStatement(exportAssignment);
    const statementKeys = BUILDER_KEYS[exportStatement.type] as
      | (keyof t.ExpressionStatement & string)[]
      | undefined;
    if (statementKeys) {
      for (const key of statementKeys) {
        validate(exportStatement, key, exportStatement[key]);
      }
    }
    path.pushContainer("body", exportStatement);
  } else {
    throw new Error("Unexpected helper format.");
  }

  const renameNames = Object.keys(toRename);
  for (let renameIndex = 0; renameIndex < renameNames.length; renameIndex++) {
    const name = renameNames[renameIndex];
    const nextName = toRename[name];
    if (nextName && nextName !== name) {
      path.scope.rename(name, nextName);
    }
  }

  for (const importPath of imps) {
    importPath.remove();
  }

  for (const refPath of impsBindingRefs) {
    const refName = refPath.node.name;
    const source = dependenciesRefs[refName];
    if (!source) {
      continue;
    }
    const cloned = cloneNode(source);
    if (cloned.type === "Identifier") {
      const identifierSource = source as t.Identifier;
      const identifierClone = cloned as t.Identifier;
      identifierClone.name = identifierSource.name;
      const identifierFields = [
        "optional",
        "loc",
        "leadingComments",
        "innerComments",
        "trailingComments",
        "extra",
        "typeAnnotation",
        "decorators",
      ];
      for (const fieldName of identifierFields) {
        if (Object.prototype.hasOwnProperty.call(identifierSource, fieldName)) {
          (identifierClone as any)[fieldName] = (identifierSource as any)[
            fieldName
          ];
        }
      }
      const identifierKeys = BUILDER_KEYS[cloned.type] as string[] | undefined;
      if (identifierKeys) {
        for (const key of identifierKeys) {
          const fields = NODE_FIELDS[cloned.type];
          if (fields) {
            const field = fields[key];
            if (field) {
              if (field.validate) {
                const val = (cloned as any)[key];
                if (!(field.optional && val == null)) {
                  validate(cloned, key, val);
                }
              } else {
                validate(cloned, key, (cloned as any)[key]);
              }
            }
          }
        }
      }
    } else if (cloned.type === "MemberExpression") {
      const memberSource = source as t.MemberExpression;
      const memberClone = cloned as t.MemberExpression;
      memberClone.object = memberSource.object;
      memberClone.property = memberSource.property;
      memberClone.computed = memberSource.computed;
      memberClone.optional = memberSource.optional;
      const memberKeys = BUILDER_KEYS[cloned.type] as string[] | undefined;
      if (memberKeys) {
        for (const key of memberKeys) {
          validate(cloned, key, (cloned as any)[key]);
        }
      }
    } else {
      const otherKeys = BUILDER_KEYS[cloned.type] as string[] | undefined;
      if (otherKeys) {
        for (const key of otherKeys) {
          validate(cloned, key, (cloned as any)[key]);
        }
      }
    }
    refPath.replaceWith(cloned);
  }
}

interface HelperData {
  build: (
    getDependency: GetDependency,
    id: t.Identifier | t.MemberExpression,
    localBindings: string[],
  ) => {
    nodes: t.Program["body"];
    globals: string[];
  };
  minVersion: string;
  getDependencies: () => string[];
}

const helperData: Record<string, HelperData> = Object.create(null);
function loadHelper(name: string) {
  if (!helperData[name]) {
    const helper = helpers[name];
    if (!helper) {
      throw Object.assign(new ReferenceError(`Unknown helper ${name}`), {
        code: "BABEL_HELPER_UNKNOWN",
        helper: name,
      });
    }

    const fn = (): File => {
      if (!process.env.BABEL_8_BREAKING) {
        if (!FileClass) {
          const fakeFile = { ast: file(helper.ast()), path: null } as File;
          traverse(fakeFile.ast, {
            Program: path => (fakeFile.path = path).stop(),
          });
          return fakeFile;
        }
      }
      return new FileClass(
        { filename: `babel-helper://${name}` },
        {
          ast: file(helper.ast()),
          code: "[internal Babel helper code]",
          inputMap: null,
        },
      );
    };

    // We compute the helper metadata lazily, so that we skip that
    // work if we only need the `.minVersion` (for example because
    // of a call to `.availableHelper` when `@babel/runtime`).
    let metadata: HelperMetadata | null = null;

    helperData[name] = {
      minVersion: helper.minVersion,
      build(getDependency, id, localBindings) {
        const file = fn();
        metadata ||= getHelperMetadata(file);
        permuteHelperAST(file, metadata, id, localBindings, getDependency);

        return {
          nodes: file.ast.program.body,
          globals: metadata.globals,
        };
      },
      getDependencies() {
        metadata ||= getHelperMetadata(fn());
        return Array.from(metadata.dependencies.values());
      },
    };
  }

  return helperData[name];
}

export function get(
  name: string,
  getDependency?: GetDependency,
  id?: t.Identifier | t.MemberExpression,
  localBindings?: string[],
) {
  return loadHelper(name).build(getDependency, id, localBindings);
}

export function minVersion(name: string) {
  return loadHelper(name).minVersion;
}

export function getDependencies(name: string): ReadonlyArray<string> {
  return loadHelper(name).getDependencies();
}

export function ensure(name: string, newFileClass: typeof File) {
  // We inject the File class here rather than importing it to avoid
  // circular dependencies between @babel/core and @babel/helpers.
  FileClass ||= newFileClass;

  loadHelper(name);
}

export const list = Object.keys(helpers).map(name => name.replace(/^_/, ""));

export default get;

