docker exec cli-eval-opencode-babel__babel-16130-250a8bc0 sh -lc 'cd /testbed && cat > debug.cjs <<"EOF"
const babel = require("./packages/babel-core");
console.log(babel.transformSync(
  "let set; class C { foo() { super.bar = 1; } }",
  { plugins: [require("./packages/babel-plugin-transform-classes")], configFile: false, babelrc: false }
).code.split("\n")[3].slice(0, 60));
const out2 = babel.transformSync(
  "const set = { foo() { super.bar = 1; } };",
  { plugins: [require("./packages/babel-plugin-transform-object-super")], configFile: false, babelrc: false }
).code.split("\n").slice(0,2).map(l=>l.slice(0,50));
console.log(out2);
EOF
node debug.cjs; rm debug.cjs'

